      { q:'Что происходит с новостью («خَبَرٌ») после «إِنَّ وَأَخَوَاتِهَا»?', opts:['Остаётся مرفوع','Становится منصوب','Становится مجزوم'], a:0 },
      { q:'Какое слово из списка НЕ является مرفوع?', opts:['«الْفَاعِلُ»','«الْمُبْتَدَأُ»','«اسْمُ إِنَّ»'], a:2 },
      { q:'Какое слово из списка НЕ является مرفوع?', opts:['«خَبَرُ إِنَّ»','«خَبَرُ كَانَ»','«نَائِبُ الْفَاعِلِ»'], a:1 },
      { q:'Что такое «التَّابِعُ لِلْمَرْفُوعِ»?', opts:['Глагол в Раф\'е','Слово, которое копирует Раф\' у предыдущего слова','Предлог'], a:1 },
      { q:'Сколько существует зависимых слов («التَّوَابِعُ»)?', opts:['Два','Три','Четыре'], a:2 },
      { q:'Какое из этих слов относится к «التَّوَابِعُ» (копирующим И\'раб)?', opts:['«الْفَاعِلُ»','«النَّعْتُ» (описание)','«الْمُبْتَدَأُ»'], a:1 },
      { q:'Является ли «الْعَطْفُ» (соединение союзом) одним из «التَّوَابِعُ»?', opts:['Да','Нет','Только في النصب'], a:0 },
      { q:'Какое из этих слов относится к «التَّوَابِعُ»?', opts:['«الْبَدَلُ» (замена)','«اسْمُ كَانَ»','«الخَبَرُ»'], a:0 },
      { q:'Какое из этих слов относится к «التَّوَابِعُ»?', opts:['«التَّوْكِيدُ» (усиление)','«الْفَاعِلُ»','«اسْمُ إِنَّ»'], a:0 },
      { q:'Определи И\'раб слова «زَيْدٌ» в предложении «قَامَ زَيْدٌ»:', opts:['مرفوع (потому что это «فَاعِلٌ»)','منصوب','مجرور'], a:0 },
      { q:'Определи И\'раб слова «زَيْدٌ» в предложении «زَيْدٌ قَائِمٌ»:', opts:['منصوب','مرفوع (потому что это «مُبْتَدَأٌ»)','مجرور'], a:1 },
      { q:'Определи И\'раб слова «قَائِمٌ» в предложении «زَيْدٌ قَائِمٌ»:', opts:['مرفوع (потому что это «خَبَرٌ»)','منصوب','مجرور'], a:0 },
      { q:'Если слово «الزَّيْدَانِ» (двое Зейдов) выступает как Файл, какой знак Раф\'а оно возьмёт?', opts:['«الضَّمَّةُ»','«الأَلِفُ»','«الوَاوُ»'], a:1 },
      { q:'Перечисли все 7 «الْمَرْفُوعَاتُ» (имена в состоянии Раф\'), как указано в матне.', open:true }
