      { q:'В скольких вещах из И\'раба На\'т копирует «الْمَنْعُوتُ» (описываемое)?', opts:['Только في الرفع','«فِي رَفْعِهِ وَنَصْبِهِ وَخَفْضِهِ» (В Раф\'е, Насбе и Хафде)','Только في الجزم'], a:1 },
      { q:'В чём ЕЩЁ (кроме И\'раба) На\'т копирует «الْمَنْعُوتُ»?', opts:['В значении','«وَتَعْرِيفِهِ وَتَنْكِيرِهِ» (В определённости и неопределённости)','В количестве букв'], a:1 },
      { q:'Выбери верный На\'т для МАРФУ\':', opts:['«قَامَ زَيْدٌ الْعَاقِلَ»','«قَامَ زَيْدٌ الْعَاقِلُ»','«قَامَ زَيْدٌ الْعَاقِلِ»'], a:1 },
      { q:'Выбери верный На\'т для МАНСУБ:', opts:['«رَأَيْتُ زَيْدًا الْعَاقِلَ»','«رَأَيْتُ زَيْدًا الْعَاقِلُ»','«رَأَيْتُ زَيْدًا الْعَاقِلِ»'], a:0 },
      { q:'Сколько видов «الْمَعْرِفَةُ» (Определённых имён) существует?', opts:['Три','«خَمْسَةُ أَشْيَاءَ» (Пять)','Семь'], a:1 },
      { q:'Что такое «الِاسْمُ الْمُضْمَرُ»?', opts:['Местоимение (например: «أَنَا» и «أَنْتَ»)','Имя собственное','Указательное'], a:0 },
      { q:'Что такое «الِاسْمُ الْعَلَمُ»?', opts:['Имя собственное (например: «زَيْدٌ» и «مَكَّةُ»)','Слово с ال','Местоимение'], a:0 },
      { q:'Что такое «الِاسْمُ الْمُبْهَمُ»?', opts:['Слово с التنوين','Указательное местоимение (например: «هَذَا»، «هَذِهِ»، «هَؤُلَاءِ»)','Глагол'], a:1 },
      { q:'Какое слово стало مَعْرِفَة بسبب «الْأَلِفِ وَاللَّامِ»?', opts:['«أَنَا»','«زَيْدٌ»','«الرَّجُلُ» и «الْغُلَامُ»'], a:2 },
      { q:'Что такое "пятый" вид Ма\'рифа?', opts:['Глаголы','«مَا أُضِيفَ إِلَى وَاحِدٍ مِنْ هَذِهِ الْأَرْبَعَةِ» (Слово, присоединенное مضاف к одному из четырёх)','Любое слово'], a:1 },
      { q:'Что такое «النَّكِرَةُ» (Неопределённое имя)?', opts:['Имя собственное','«كُلُّ اسْمٍ شَائِعٍ فِي جِنْسِهِ» (Общее имя, не указывающее на конкретное)','Местоимение'], a:1 },
      { q:'Какой простой признак для النَّكِرَةُ даёт автор?', opts:['Танвин в начале','«كُلُّ مَا صَلَحَ دُخُولُ الْأَلِفِ وَاللَّامِ عَلَيْهِ» (Всё, к чему можно прикрепить ال)','Наличие касры'], a:1 },
      { q:'Если «الْمَنْعُوتُ» — это «زَيْدٌ», какой На\'т к нему подойдет?', opts:['«عَاقِلٌ» (нَكِرَة)','«الْعَاقِلُ» (мَعْرِفَة)'], a:1 },
      { q:'И\'раб слова «الْعَاقِلِ» в фразе «مَرَرْتُ بِزَيْدٍ الْعَاقِلِ»:', opts:['مضاف إليه','نعت مجرور وعلامة جره الكسرة','اسم مجرور بالباء'], a:1 },
      { q:'Если «الْمَنْعُوتُ» — это «رَجُلٌ» (без ال), то На\'т будет:', opts:['«الْعَاقِلُ»','«عَاقِلٌ»','«الْعَاقِلَ»'], a:1 },
      { q:'Является ли «هَذَا» مَعْرِفَة?', opts:['Да, это «الِاسْمُ الْمُبْهَمُ»','Нет, это نكرة','Только مضاف'], a:0 },
      { q:'Является ли «أَنَا» مَعْرِفَة?', opts:['Да, это «الِاسْمُ الْمُضْمَرُ»','Нет, это حرف','Нет, это نكرة'], a:0 },
      { q:'Является ли «رَجُلٌ» مَعْرِفَة?', opts:['Да','Нет, это نكرة لأنه شائع','Только إذا كان مرفوعا'], a:1 },
      { q:'Назови 5 видов ОПРЕДЕЛЁННЫХ имён («الْمَعْرِفَةُ»).', open:true }
